{"policy":"permit (
    principal is Pathologist,
    action == Action::"releaseLabResult",
    resource is LabResult
);

permit (
    principal is OrderingProvider,
    action == Action::"releaseLabResult",
    resource is LabResult
);

forbid (
    principal,
    action == Action::"releaseLabResult",
    resource is LabResult
)
when {
    resource has verifiedBy &&
    resource.verifiedBy.user == principal.user
};

forbid (
    principal,
    action == Action::"releaseLabResult",
    resource is LabResult
)
when {
    !resource.isVerified
};

forbid (
    principal is OrderingProvider,
    action == Action::"releaseLabResult",
    resource is LabResult
)
when {
    resource.sensitivityLevel == "restricted" &&
    !resource.criticalValueFlag
};"}
